{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'auth', 'storage', 'extensions', 'pgbouncer')
ORDER BY table_schema, table_name;
"}

{"query": "
-- Verify indexes
SELECT indexname, tablename FROM pg_indexes 
WHERE schemaname = 'employees' 
  AND indexname IN ('idx_projects_status','idx_assignments_emp_proj','idx_milestones_due_date');
"}

{"query": "
SELECT milestone_id, project_id, milestone_name, due_date, completed
FROM employees.project_milestones
ORDER BY project_id, due_date;
"}

{"query": "
SELECT project_id, project_name, start_date, end_date, budget, status, priority
FROM employees.employee_projects ORDER BY project_id;
"}
